function txt(parent, s, x,y,w, size, style, color, opts){
  const t = figma.createText();
  parent.appendChild(t);
  t.fontName = {family:'Inter', style:style};
  t.fontSize = size;
  if(opts && opts.lh) t.lineHeight = {unit:'PIXELS', value: opts.lh};
  if(opts && opts.ls) t.letterSpacing = {unit:'PIXELS', value: opts.ls};
  if(opts && opts.center) t.textAlignHorizontal='CENTER';
  t.characters = s;
  t.fills = [{type:'SOLID', color: rgb(color||INK)}];
  t.x=x; t.y=y;
  if(w){ t.resize(w, t.height); t.textAutoResize='HEIGHT'; }
  if(opts && opts.name) t.name = opts.name;
  return t;
}
async function cloneComp(id, parent, x, y, name){
  const src = await figma.getNodeByIdAsync(id);
  const c = src.clone();
  parent.appendChild(c);
  c.x=x; c.y=y;
  if(name) c.name = name;
  return c;
}
function recolor(n, color){
  const all = [n, ...n.findAll(()=>true)];
  for(const k of all){
    if(k.fills && k.fills.length && k.fills.every(f=>f.type==='SOLID')) k.fills = k.fills.map(f=>({...f, color: rgb(color)}));
    if(k.strokes && k.strokes.length) k.strokes = k.strokes.map(f=>({...f, color: rgb(color)}));
  }
}

