function txt(parent, s, opts){
  const t = figma.createText();
  parent.appendChild(t);
  t.fontName = {family:'Inter', style:opts.style||'Regular'};
  t.fontSize = opts.size||15;
  if(opts.lh) t.lineHeight = {unit:'PIXELS', value:opts.lh};
  if(opts.ls!==undefined) t.letterSpacing = {unit:'PIXELS', value:opts.ls};
  t.characters = s;
  t.fills = [solid(opts.color||INK)];
  if(opts.w){ t.resize(opts.w, t.height); t.textAutoResize='HEIGHT'; }
  if(opts.align) t.textAlignHorizontal = opts.align;
  t.x = opts.x||0; t.y = opts.y||0;
  if(opts.name) t.name = opts.name;
  return t;
}
