const TEAL='#007A8C', GREEN='#336749', INK='#101418', MUTED='#6B7480', WHITE='#FFFFFF';
const rgb = h => ({r:parseInt(h.slice(1,3),16)/255,g:parseInt(h.slice(3,5),16)/255,b:parseInt(h.slice(5,7),16)/255});
const solid = h => ({type:'SOLID', color: rgb(h)});
const REF={};
async function ref(id){ if(!REF[id]) REF[id]=await figma.getNodeByIdAsync(id); return REF[id]; }
function txt(parent,s,o){
  const t=figma.createText(); parent.appendChild(t);
  t.fontName={family:'Inter',style:o.style||'Regular'}; t.fontSize=o.size||15;
  if(o.lh) t.lineHeight={unit:'PIXELS',value:o.lh};
  if(o.ls!==undefined) t.letterSpacing={unit:'PIXELS',value:o.ls};
  t.characters=s; t.fills=[solid(o.color||INK)];
  if(o.w){t.resize(o.w,t.height);t.textAutoResize='HEIGHT';}
  if(o.align) t.textAlignHorizontal=o.align;
  t.x=o.x||0;t.y=o.y||0;
  return t;
}
async function icon(parent,id,x,y,color,size){
  const src=await ref(id); const c=src.clone(); parent.appendChild(c); c.x=x;c.y=y;
  if(size){const k=size/Math.max(c.width,c.height); if(Math.abs(k-1)>0.001) c.rescale(k);}
  for(const k of [c,...c.findAll(()=>true)]){
    if(k.fills&&k.fills.length&&k.fills.every(f=>f.type==='SOLID')) k.fills=k.fills.map(f=>({...f,color:rgb(color)}));
    if(k.strokes&&k.strokes.length) k.strokes=k.strokes.map(f=>({...f,color:rgb(color)}));
  }
  return c;
}
function photo(parent,hash,x,y,w,h,r){
  const rect=figma.createRectangle(); parent.appendChild(rect);
  rect.x=x;rect.y=y;rect.resize(w,h);
  rect.fills=[{type:'IMAGE',imageHash:hash,scaleMode:'FILL'}];
  if(r) rect.cornerRadius=r;
  return rect;
}
async function statusBar(f,light){
  const c=(await ref('1:36')).clone(); f.appendChild(c); c.x=0;c.y=0;
  if(light){ for(const k of [c,...c.findAll(()=>true)]){ if(k.fills&&k.fills.length&&k.fills.every(x=>x.type==='SOLID')) k.fills=k.fills.map(x=>({...x,color:rgb(WHITE)})); if(k.strokes&&k.strokes.length) k.strokes=k.strokes.map(x=>({...x,color:rgb(WHITE)})); } }
}
async function homeInd(f,y,dark){
  const c=(await ref('1:46')).clone(); f.appendChild(c); c.x=0;c.y=y;
  if(!dark){ for(const k of [c,...c.findAll(()=>true)]){ if(k.fills&&k.fills.length) k.fills=k.fills.map(x=>({...x,color:rgb('#8A9097')})); } }
}

